    void rec::patch(patchList l, Prog* p, uint32_t val)
    {
        auto head = l.head;
        for(; head != 0; )
        {
            auto i = & p->Inst[head >> 1];
            if(head & 1 == 0)
            {
                head = i->Out;
                i->Out = val;
            }
            else
            {
                head = i->Arg;
                i->Arg = val;
            }
        }
    }

